// Flujo GENERAL de documentos (30-sep-2026).
// n8n ya no arma el HTML: la plataforma llena la plantilla (Cloud Function,
// versionada en git) y aquí solo se convierte a PDF. Así un documento nuevo
// (carta encomienda de otra naviera, HBL, booking…) no requiere flujo nuevo.
//
// Body esperado (JSON):
//   html          string   documento HTML completo, UTF-8. Imágenes en data: URI.
//   nombreArchivo string   p. ej. "VLIM-2026-0042-carta-encomienda-cosco-v1.pdf"
//   tipo          string   p. ej. "carta_encomienda" (solo para el log)
//   pagina        objeto   opcional: { ancho, alto } en pulgadas y
//                          { margenSup, margenInf, margenIzq, margenDer } en pulgadas.
//                          Si no viene, manda el @page del CSS de la plantilla.
const body = $input.first().json.body || $input.first().json;
const html = body.html;

if (typeof html !== 'string' || !/<html[\s>]/i.test(html)) {
  throw new Error('Falta «html» o no es un documento HTML completo.');
}
const bytesHtml = Buffer.byteLength(html, 'utf8');
if (bytesHtml > 8 * 1024 * 1024) {
  throw new Error('El HTML pesa ' + Math.round(bytesHtml / 1024) + ' KB; el límite es 8 MB.');
}

const limpio = s => String(s || '').replace(/[^\w.\-]+/g, '-').replace(/-+/g, '-').slice(0, 120);
let nombre = limpio(body.nombreArchivo) || ('documento-' + Date.now());
if (!/\.pdf$/i.test(nombre)) nombre += '.pdf';

// Tamaño y márgenes: número en pulgadas o vacío. Vacío = lo decide el CSS.
const num = v => (v === undefined || v === null || v === '' || isNaN(Number(v))) ? '' : String(Number(v));
const p = body.pagina || {};
const gotenberg = {
  preferCssPageSize: 'true',
  printBackground: 'true',
  paperWidth: num(p.ancho) || '8.5',
  paperHeight: num(p.alto) || '11',
  marginTop: num(p.margenSup) || '0',
  marginBottom: num(p.margenInf) || '0',
  marginLeft: num(p.margenIzq) || '0',
  marginRight: num(p.margenDer) || '0',
};

// Gotenberg exige que el archivo se llame index.html. La propiedad binaria
// se llama «archivo» (sin punto: n8n lee «a.b» como ruta anidada).
const archivo = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{
  json: { nombreArchivo: nombre, tipo: String(body.tipo || ''), bytesHtml, gotenberg },
  binary: { archivo },
}];

const item = $input.first();
const origen = $('Arma el archivo').first().json;
const bin = item.binary && item.binary.pdf;
if (!bin) {
  throw new Error('Gotenberg no devolvió el archivo PDF.');
}
// Un PDF válido empieza con «%PDF-». Si Gotenberg devolvió otra cosa, es error.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'pdf');
if (buffer.subarray(0, 5).toString('latin1') !== '%PDF-') {
  throw new Error('Gotenberg devolvió algo que no es un PDF: ' + buffer.subarray(0, 40).toString('latin1'));
}
bin.fileName = origen.nombreArchivo;
bin.mimeType = 'application/pdf';
return [{ json: { ok: true, nombreArchivo: origen.nombreArchivo, tipo: origen.tipo, bytes: buffer.length }, binary: { pdf: bin } }];

// Rama de error: el HTML no llegó bien, Gotenberg falló o no devolvió PDF.
// Se contesta JSON para que la plataforma lo muestre; el detalle queda en la
// ejecución de n8n.
const item = $input.first();
const detalle = (item.json && (item.json.error && (item.json.error.message || item.json.error))) || item.json?.message || 'sin detalle';
return [{ json: {
  ok: false,
  error: 'El generador de documentos falló al armar el PDF. Vuelve a intentarlo; si se repite, avisa a sistemas.',
  detalle: String(detalle).slice(0, 500),
} }];
